CREATE COLUMN TABLE "TEST_AP"."OBFC" ("AbsEntry" INTEGER CS_INT NOT NULL , "FldType" NVARCHAR(1) NOT NULL , "FldNum" SMALLINT CS_INT NOT NULL , "DispName" NVARCHAR(20), "Activated" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "DataSource" NVARCHAR(1) DEFAULT 'N', "Transfered" NVARCHAR(1) DEFAULT 'N', "Instance" SMALLINT CS_INT DEFAULT 0, "LogInstanc" INTEGER CS_INT DEFAULT 0, "CreateDate" LONGDATE CS_LONGDATE, "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "DftName" NVARCHAR(20), PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OBFC_BUSINESS_K" ON "TEST_AP"."OBFC" ( "FldType" ASC, "FldNum" ASC )